"""Deterministic analyzer: edge chain, checkpoint-vs-now unified diff, template explanation. No model call."""
import difflib
import subprocess

from .errors import NotFound
from . import tree as treemod

PHRASE = {"reads": "reads", "produced_by": "is produced by", "traces_to": "traces to", "includes": "includes",
          "generated_by": "is generated by", "executes": "runs", "imports": "imports", "value_match": "was linked by you to"}
MAX_DIFF_LINES = 400


def chain_for(group, node_id, edges_by_id):
    changed = {c["node_id"] for c in group["changed"]}
    if node_id in changed:
        return [node_id], []
    down = {d["node_id"]: d for d in group["downstream"]}
    if node_id not in down:
        raise NotFound("node %r is not in group %r" % (node_id, group["id"]))
    nodes, edges = [node_id], []
    cur = node_id
    while cur not in changed:
        via = down[cur]["via"]
        edges.append(via)
        cur = edges_by_id[via]["to"]
        nodes.append(cur)
    nodes.reverse()
    edges.reverse()
    return nodes, edges


def _cp_text(cp, nid, hub, infos):
    ent = cp["nodes"].get(nid)
    if not ent:
        return b"", None
    blob = ent.get("blob")
    data = hub.get_blob(blob) if blob else None
    if data is None and ent.get("path"):
        info = infos.get(ent["repo"])
        rev = cp["repos"].get(ent["repo"], {}).get("rev")
        if info and info["vcs"] == "git" and rev:
            p = treemod.run_git(info["abs_path"], ["show", "%s:%s" % (rev, ent["path"])], check=False)
            if p.returncode == 0:
                data = p.stdout
    return data if data is not None else b"", ent


def _diff_one(cp, node, trees, hub, infos):
    nid = node["id"]
    path = node["loc"]["path"]
    old, ent = _cp_text(cp, nid, hub, infos)
    new = trees[node["repo"]].read(path) or b""
    d = {"node_id": nid, "repo": node["repo"], "path": path, "from_label": "checkpoint %s" % cp["id"], "to_label": "now",
         "binary": False, "truncated": False, "unified": ""}
    if b"\0" in old[:8192] or b"\0" in new[:8192]:
        d["binary"] = True
        return d
    a = old.decode("utf-8", "replace").splitlines(keepends=True)
    b = new.decode("utf-8", "replace").splitlines(keepends=True)
    a = [x if x.endswith("\n") else x + "\n" for x in a]
    b = [x if x.endswith("\n") else x + "\n" for x in b]
    lines = list(difflib.unified_diff(a, b, "a/%s (%s)" % (path, cp["id"]), "b/%s (now)" % path, n=2))
    if len(lines) > MAX_DIFF_LINES:
        lines, d["truncated"] = lines[:MAX_DIFF_LINES], True
    d["unified"] = "".join(lines)
    return d


def explain(chain_nodes, chain_edges, nodes, edges_by_id, group, alarms_cp_nodes):
    first = nodes[chain_nodes[0]]
    cause = group["cause"]
    ch = next(c for c in group["changed"] if c["node_id"] == chain_nodes[0])
    if cause["kind"] == "commit":
        where = 'in %s ("%s")' % (cause["short"], cause["subject"])
    elif cause["kind"] == "worktree":
        where = "in uncommitted changes"
    else:
        where = "since the checkpoint"
    verb = "was added" if ch["change"] == "added" else "changed"
    parts = ["%s %s %s." % (first["name"], verb, where)]
    for i, eid in enumerate(chain_edges):
        e = edges_by_id[eid]
        x, y = nodes[e["from"]], nodes[e["to"]]
        obj = "it" if i == 0 else y["name"]
        s = "%s %s %s" % (x["name"], PHRASE.get(e["kind"], e["kind"]), obj)
        if x["kind"] in ("result", "asset"):
            h0 = alarms_cp_nodes.get(x["id"], {}).get("hash")
            if h0 == x["hash"]:
                s += " and is byte-identical to the checkpoint (not regenerated, or regenerated identically)"
        parts.append(s + ".")
    return " ".join(parts)


def analyze(group_id, node_id, alarms, cp, nodes, edges, trees, hub, infos):
    group = next((g for g in alarms["groups"] if g["id"] == group_id), None)
    if group is None:
        raise NotFound("unknown alarm group %r" % group_id)
    edges_by_id = {e["id"]: e for e in edges}
    cn, ce = chain_for(group, node_id, edges_by_id)
    diffs = []
    ch = next((c for c in group["changed"] if c["node_id"] == cn[0]), None)
    if ch is not None and cn[0] in nodes:
        diffs.append(_diff_one(cp, nodes[cn[0]], trees, hub, infos))
    return {"group_id": group_id, "node_id": node_id, "chain": {"nodes": cn, "edges": ce}, "diffs": diffs,
            "explanation": explain(cn, ce, nodes, edges_by_id, group, cp["nodes"]),
            "ai": {"available": False, "label": "Ask Claude why — not available in this demo"}}
